#include <iostream>
#include <iomanip>

// Deterministic demonstration of scaling and shifting
// Formula: face = shift + value % scalingFactor
int main() {
    // Representative sequence of pseudo-random integers
    const int simulatedValues[10] = {
        100, 105, 102, 107, 104,
        103, 101, 106, 108, 109
    };

    const int shift = 1;
    const int scalingFactor = 6;

    std::cout << "Simulated 10 die rolls (1 + val % 6):\n";
    for (int i = 0; i < 10; ++i) {
        int face = shift + (simulatedValues[i] % scalingFactor);
        std::cout << std::setw(4) << face;
        if ((i + 1) % 5 == 0) {
            std::cout << "\n";
        }
    }

    return 0;
}
